/** Makes Track-only attribution deliberately disagree with the Album's own attribution. */
const seedIndependentTrackAttribution = async () => {
    const ids = await seed();
    await getDb()!.collection('albums').updateOne({ _id: ids.albumId }, {
        $set: { audioTrackIds: [ids.trackId.toHexString()] }
    });
    await getDb()!.collection('audioTracks').updateOne({ _id: ids.trackId }, {
        $set: {
            albumId: ids.albumId.toHexString(),
            artistIds: [ids.featuredId.toHexString()],
            s3Key: ids.trackId.toHexString()
        }
    });
    return ids;
};

test('Organization-only Album attribution stays independent of its ready component Track', async () => {
    const { organizationId, albumId } = await seedIndependentTrackAttribution();
    await replaceCatalogCredits('album', albumId.toHexString(), [{
        creditId: 'album_only_label', subjectType: 'organization',
        subjectId: organizationId.toHexString(), role: 'label'
    }], 'documented');
    const listener = await getListenerAlbum(albumId.toHexString());
    assert.deepEqual(listener?.album.artistNames, []);
    assert.equal(listener?.album.displayByline, 'Release House');
    assert.deepEqual(listener?.tracks[0].artistNames, ['Featured']);
});

test('explicit unknown Album attribution never inherits its ready component Track or stale legacy membership', async () => {
    const { artistId, albumId } = await seedIndependentTrackAttribution();
    await replaceCatalogCredits('album', albumId.toHexString(), [], 'unknown');
    // A stale compatibility projection must not override a canonical empty attribution.
    await getDb()!.collection('artists').updateOne({ _id: artistId }, {
        $set: { albumIds: [albumId.toHexString()] }
    });
    const listener = await getListenerAlbum(albumId.toHexString());
    assert.deepEqual(listener?.album.artistNames, []);
    assert.equal(listener?.album.displayByline, 'Attribution not documented');
    assert.deepEqual(listener?.tracks[0].artistNames, ['Featured']);
});

test('unmigrated Album attribution uses only its legacy Album Artist relationship', async () => {
    const { artistId, albumId } = await seedIndependentTrackAttribution();
    await getDb()!.collection('artists').updateOne({ _id: artistId }, {
        $set: { albumIds: [albumId.toHexString()] }
    });
    const listener = await getListenerAlbum(albumId.toHexString());
    assert.deepEqual(listener?.album.artistNames, ['Primary']);
    assert.deepEqual(listener?.tracks[0].artistNames, ['Featured']);
    await getDb()!.collection('artists').updateOne({ _id: artistId }, { $set: { albumIds: [] } });
    assert.deepEqual((await getListenerAlbum(albumId.toHexString()))?.album.artistNames, []);
});

test('canonical Album attribution with an unavailable Artist does not reveal stale legacy attribution', async () => {
    const { artistId, featuredId, albumId } = await seedIndependentTrackAttribution();
    await replaceCatalogCredits('album', albumId.toHexString(), [{
        creditId: 'album_primary_unavailable', subjectType: 'artist',
        subjectId: artistId.toHexString(), role: 'primary'
    }], 'documented');
    await getDb()!.collection('artists').updateOne({ _id: artistId }, { $set: { lifecycleStatus: 'deleting' } });
    await getDb()!.collection('artists').updateOne({ _id: featuredId }, { $set: { albumIds: [albumId.toHexString()] } });
    assert.deepEqual((await getListenerAlbum(albumId.toHexString()))?.album.artistNames, []);
});

test('Credit read rollback uses only the Album compatibility relationship', async () => {
    const { artistId, albumId } = await seedIndependentTrackAttribution();
    await replaceCatalogCredits('album', albumId.toHexString(), [{
        creditId: 'album_primary_rollback', subjectType: 'artist',
        subjectId: artistId.toHexString(), role: 'primary'
    }], 'documented');
    const previous = process.env.CATALOG_CREDIT_READS_ENABLED;
    process.env.CATALOG_CREDIT_READS_ENABLED = 'false';
    try {
        const listener = await getListenerAlbum(albumId.toHexString());
        assert.deepEqual(listener?.album.artistNames, ['Primary']);
        assert.equal(listener?.album.credits, undefined);
        assert.deepEqual(listener?.tracks[0].artistNames, ['Featured']);
    } finally {
        if (previous === undefined) delete process.env.CATALOG_CREDIT_READS_ENABLED;
        else process.env.CATALOG_CREDIT_READS_ENABLED = previous;
    }
});

test('Organization releases resolve publicly and deletion is blocked until Credits are removed', async () => {
    const { organizationId, albumId } = await seed();
    await replaceCatalogCredits('album', albumId.toHexString(), [{
        creditId: 'credit_label',
        subjectType: 'organization',
        subjectId: organizationId.toHexString(),
        role: 'label'
    }], 'documented');
    const detail = await getListenerOrganization(organizationId.toHexString());
    assert.equal(detail?.organization.name, 'Release House');
    assert.deepEqual(detail?.releases.map((album) => album.id), [albumId.toHexString()]);
    const legacyClientDetail = await getPublicOrganization(organizationId.toHexString());
    assert.equal(legacyClientDetail?.organization.name, 'Release House');
    assert.deepEqual(
        legacyClientDetail?.releases.map((album) => album._id),
        [albumId.toHexString()]
    );
    const search = await searchPublicCatalog('Release House', 20);
    assert.deepEqual(search.organizations.map((organization) => organization._id), [
        organizationId.toHexString()
    ]);
    await assert.rejects(
        deleteUnreferencedOrganization(organizationId.toHexString()),
        (error: any) => error?.code === 'organization_referenced'
    );
    assert.equal(
        (await getDb()!.collection('organizations').findOne({ _id: organizationId }))?.lifecycleStatus,
        'ready'
    );
    await replaceCatalogCredits('album', albumId.toHexString(), [], 'unknown', 1);
    await deleteUnreferencedOrganization(organizationId.toHexString());
    assert.equal(await getDb()!.collection('organizations').findOne({ _id: organizationId }), null);
});

// Join phrases. Explicit replacements store exactly the phrases they carry; every other rebuild
// keeps a phrase only while the same Credit still follows it.
const phraseCredit = (creditId: string, subjectId: ObjectId, role: string, joinPhrase?: string) => ({
    creditId,
    subjectType: 'artist',
    subjectId: subjectId.toHexString(),
    role,
    ...(joinPhrase === undefined ? {} : { joinPhrase })
});

/** Adds two more ready Artists, named Third and Performer, to the shared seed. */
const seedPhraseCast = async () => {
    const ids = await seed();
    const thirdId = new ObjectId();
    const performerId = new ObjectId();
    await getDb()!.collection('artists').insertMany([
        { _id: thirdId, name: 'Third', albumIds: [], lifecycleStatus: 'ready', referenceRevision: 0 },
        { _id: performerId, name: 'Performer', albumIds: [], lifecycleStatus: 'ready', referenceRevision: 0 }
    ]);
    return { ...ids, thirdId, performerId };
};

const storedCredits = async (collection: 'albums' | 'audioTracks', id: ObjectId) =>
    ((await getDb()!.collection(collection).findOne({ _id: id }))?.credits ?? []) as Array<Record<string, unknown>>;
const phrasesById = (credits: Array<Record<string, unknown>>) =>
    credits.map((credit) => [credit.creditId, credit.role, credit.joinPhrase]);

/** Runs one Content Manager form controller as an administrator and returns its decoded redirect. */
const runCreditForm = async (
    controller: (req: any, res: any, next: any) => unknown,
    body: Record<string, string>
) => {
    let redirect = '';
    let forwarded: unknown;
    const res = {
        redirect: (url: string) => { redirect = url; return res; },
        status: () => res,
        type: () => res,
        send: () => res
    };
    await controller(
        { auth: { role: 'admin', userId: new ObjectId().toHexString() }, body },
        res,
        (error: unknown) => { forwarded = error; }
    );
    assert.equal(forwarded, undefined);
    return decodeURIComponent(redirect);
};

test('Content Manager role changes keep join phrases and a reorder keeps only phrases whose next Credit is unchanged', async () => {
    const { artistId, featuredId, thirdId, performerId, albumId } = await seedPhraseCast();
    await replaceCatalogCredits('album', albumId.toHexString(), [
        phraseCredit('phrase_primary', artistId, 'primary', ' & '),
        phraseCredit('phrase_second', featuredId, 'primary'),
        phraseCredit('phrase_third', thirdId, 'featured', ' feat. '),
        phraseCredit('phrase_performer', performerId, 'performer')
    ], 'documented');

    assert.match(await runCreditForm(updateCatalogCreditRoleWeb, {
        ownerType: 'album', ownerId: albumId.toHexString(), creditId: 'phrase_third', role: 'performer'
    }), /Credit role updated successfully\./);
    assert.deepEqual(phrasesById(await storedCredits('albums', albumId)), [
        ['phrase_primary', 'primary', ' & '],
        ['phrase_second', 'primary', undefined],
        ['phrase_third', 'performer', ' feat. '],
        ['phrase_performer', 'performer', undefined]
    ]);

    // Moving Primary down changes the Credit after it, so its phrase is cleared; Third is still
    // followed by Performer and keeps its phrase.
    assert.match(await runCreditForm(reorderCatalogCreditWeb, {
        ownerType: 'album', ownerId: albumId.toHexString(), creditId: 'phrase_primary', direction: 'down'
    }), /Credit order updated successfully\./);
    const reordered = await storedCredits('albums', albumId);
    assert.deepEqual(phrasesById(reordered), [
        ['phrase_second', 'primary', undefined],
        ['phrase_primary', 'primary', undefined],
        ['phrase_third', 'performer', ' feat. '],
        ['phrase_performer', 'performer', undefined]
    ]);
    assert.equal('joinPhrase' in reordered[1], false);
    assert.equal((await getListenerAlbum(albumId.toHexString()))?.album.displayByline, 'Featured, Primary, Third feat. Performer');
});

test('a Content Manager role change succeeds over an invalid stored phrase and repairs it', async () => {
    const { artistId, featuredId, albumId } = await seedPhraseCast();
    await replaceCatalogCredits('album', albumId.toHexString(), [
        phraseCredit('phrase_primary', artistId, 'primary'),
        phraseCredit('phrase_second', featuredId, 'featured', ' & ')
    ], 'documented');
    await getDb()!.collection('albums').updateOne({ _id: albumId }, { $set: { 'credits.0.joinPhrase': 'x\u200By' } });

    assert.match(await runCreditForm(updateCatalogCreditRoleWeb, {
        ownerType: 'album', ownerId: albumId.toHexString(), creditId: 'phrase_second', role: 'primary'
    }), /Credit role updated successfully\./);
    const credits = await storedCredits('albums', albumId);
    assert.deepEqual(phrasesById(credits), [
        ['phrase_primary', 'primary', undefined],
        ['phrase_second', 'primary', ' & ']
    ]);
    assert.equal('joinPhrase' in credits[0], false);
});

